/**
 * Returns a Map of { fromLang_word → toLang_word } for offline translation.
 * Uses the CLINICAL_VOCAB keyed-entry structure — no positional misalignment.
 * Each entry maps one concept across all languages via the English anchor.
 */
export function getClinicalDict(
  fromLang: SupportedLanguage,
  toLang: SupportedLanguage,
): Map<string, string> {
  const result = new Map<string, string>();
  for (const entry of CLINICAL_VOCAB) {
    const fromWord =
      fromLang === "en"
        ? entry.en
        : (entry[fromLang as keyof VocabEntry] as string | undefined);
    const toWord =
      toLang === "en"
        ? entry.en
        : (entry[toLang as keyof VocabEntry] as string | undefined);
    if (fromWord && toWord && fromWord.toLowerCase() !== toWord.toLowerCase()) {
      result.set(fromWord.toLowerCase(), toWord);
    }
  }
  return result;
}

/** @deprecated Use getClinicalDict for translation. */
export function getClinicalVocabulary(lang: SupportedLanguage): string[] {
  return CLINICAL_VOCAB.map(
    (e) => (e[lang as keyof VocabEntry] as string | undefined) ?? e.en,
  );
}

/** @deprecated Maintained for compatibility — use CLINICAL_VOCAB directly. */
export const CLINICAL_VOCABULARY: Partial<Record<SupportedLanguage, string[]>> = new Proxy(
  {} as Partial<Record<SupportedLanguage, string[]>>,
  { get: (_, lang) => getClinicalVocabulary(lang as SupportedLanguage) },
);
